function renderProgressStrip(container,data){var strip=document.createElement('div');strip.className='progress-strip';var leagueSide=document.createElement('div');leagueSide.className='progress-strip-item progress-strip-league';leagueSide.innerHTML=vEsc(data.league_icon)+' <span class="ps-label">'+vEsc(data.league_name)+'</span> <span class="ps-xp">'+data.league_xp.toLocaleString('pt-BR')+' XP</span>';leagueSide.onclick=function(){if(typeof doAction==='function')doAction(data.league_cb);};strip.appendChild(leagueSide);var achSide=document.createElement('div');achSide.className='progress-strip-item progress-strip-ach';achSide.innerHTML='\ud83c\udfc6 <span class="ps-label">'+data.ach_unlocked+'/'+data.ach_total+'</span>';achSide.onclick=function(){if(typeof doAction==='function')doAction(data.ach_cb);};strip.appendChild(achSide);container.appendChild(strip);}
function _renderBreadcrumb(container,chain){var el=document.createElement('div');el.className='v-breadcrumb';var max=4;var start=chain.length>max?chain.length-max:0;for(var i=start;i<chain.length;i++){if(i>start){var sep=document.createElement('span');sep.className='v-bc-sep';sep.textContent='›';el.appendChild(sep);}var item=chain[i];var span=document.createElement('span');span.className='v-bc-item';if(i===chain.length-1){span.classList.add('v-bc-active');}span.textContent=item.l;if(i<chain.length-1&&item.cb){span.style.cursor='pointer';span.setAttribute('data-cb',item.cb);span.onclick=function(){var cb=this.getAttribute('data-cb');if(cb&&typeof doAction==='function')doAction(cb);};}el.appendChild(span);}if(start>0){var dots=document.createElement('span');dots.className='v-bc-dots';dots.textContent='… ';el.insertBefore(dots,el.firstChild);}container.appendChild(el);}
function _renderPlayerStats(container,stats){var el=document.createElement('div');el.className='player-stats-strip';var items=[];items.push('⚔️ '+stats.kills+' abates');if(stats.max_streak>1)items.push('🔥 '+stats.max_streak+' seguidas');if(stats.strongest)items.push('💀 '+vEsc(stats.strongest));el.innerHTML=items.join(' · ');container.appendChild(el);}
function _renderDmTip(container,tip){var el=document.createElement('div');el.className='dm-tip';el.innerHTML='<span class="dm-tip-icon">📜</span> <span class="dm-tip-text">'+vEsc(tip)+'</span>';container.appendChild(el);}
function _renderReturnNarrative(container,text){var el=document.createElement('div');el.className='return-narrative';el.textContent=text;container.insertBefore(el,container.firstChild);setTimeout(function(){el.classList.add('fade-out');setTimeout(function(){if(el.parentNode)el.parentNode.removeChild(el);},1500);},4000);}
function _renderSuggestedAction(container,action){var el=document.createElement('div');el.className='suggested-action suggested-'+action.type;el.innerHTML=vEsc(action.text);el.style.cursor='pointer';el.onclick=function(){if(action.cb&&typeof doAction==='function')doAction(action.cb);};container.appendChild(el);}
function _showFirstVisitToast(title){var text='✨ Nova área descoberta: '+title;var dur=(typeof calcReadTime==='function')?calcReadTime(text,'toast'):2500;setTimeout(function(){if(typeof showToast==='function')showToast(text,dur);},500);}
function _showCombatSummaryToast(summary){if(!summary||!summary.enemy)return;var text='\u2694\ufe0f Vitória! '+summary.enemy+' derrotado em '+summary.turns+' rodada'+(summary.turns>1?'s':'')+'. +'+summary.xp+' XP, +'+summary.gold+' \ud83d\udcb0';var dur=(typeof calcReadTime==='function')?calcReadTime(text,'toast'):3500;setTimeout(function(){if(typeof showToast==='function')showToast(text,dur);},300);}
function _renderGuideHint(container,hint){if(!hint||!hint.text)return;var bubble=document.createElement('div');bubble.className='guide-bubble';var npcEl=document.createElement('div');npcEl.className='guide-npc';npcEl.textContent=hint.emoji||'📜';bubble.appendChild(npcEl);var textWrap=document.createElement('div');textWrap.className='guide-text';if(hint.npc){var nameEl=document.createElement('span');nameEl.className='guide-name';nameEl.textContent=hint.npc;textWrap.appendChild(nameEl);}var msgEl=document.createElement('span');msgEl.textContent=hint.text;textWrap.appendChild(msgEl);bubble.appendChild(textWrap);if(hint.cb_dismiss){var dismissBtn=document.createElement('button');dismissBtn.className='guide-dismiss';dismissBtn.setAttribute('aria-label','Dispensar dica');dismissBtn.textContent='✕';dismissBtn.onclick=function(e){e.stopPropagation();bubble.style.opacity='0';setTimeout(function(){if(bubble.parentNode)bubble.parentNode.removeChild(bubble);},300);if(typeof doAction==='function')doAction(hint.cb_dismiss);};bubble.appendChild(dismissBtn);}container.appendChild(bubble);setTimeout(function(){if(bubble.parentNode){bubble.style.opacity='0';setTimeout(function(){if(bubble.parentNode)bubble.parentNode.removeChild(bubble);},300);if(hint.cb_dismiss&&typeof doAction==='function')doAction(hint.cb_dismiss);}},10000);}
function _renderOpportunityCards(container,cards){if(!cards||!cards.length)return;var wrap=document.createElement('div');wrap.className='opp-cards';for(var i=0;i<cards.length;i++){(function(card){var cardEl=document.createElement('div');cardEl.className='opp-card';var textEl=document.createElement('div');textEl.className='opp-card-text';textEl.textContent=card.teaser||card.title||'';cardEl.appendChild(textEl);var acceptBtn=document.createElement('button');acceptBtn.className='opp-card-btn';acceptBtn.textContent='Aceitar';acceptBtn.onclick=function(e){e.stopPropagation();if(card.cb_accept&&typeof doAction==='function')doAction(card.cb_accept);};cardEl.appendChild(acceptBtn);var dismissBtn=document.createElement('button');dismissBtn.className='opp-card-dismiss';dismissBtn.setAttribute('aria-label','Dispensar');dismissBtn.textContent='✕';dismissBtn.onclick=function(e){e.stopPropagation();cardEl.style.opacity='0';cardEl.style.transform='translateX(30px)';setTimeout(function(){if(cardEl.parentNode)cardEl.parentNode.removeChild(cardEl);if(wrap.children.length===0&&wrap.parentNode)wrap.parentNode.removeChild(wrap);},300);if(card.cb_dismiss&&typeof doAction==='function')doAction(card.cb_dismiss);};cardEl.appendChild(dismissBtn);wrap.appendChild(cardEl);})(cards[i]);}container.appendChild(wrap);if(typeof staggerReveal==='function')staggerReveal(wrap,'.opp-card',150);}
